class Solution {
public:
    long long minEnd(int n, int x) {
        long long ans = x;
        long long v = n - 1;
        int i = 0;
        for (int j = 0; j < 64; j++) {
            if (!((ans >> j) & 1)) {
                if ((v >> i) & 1) {
                    ans |= (1LL << j);
                }
                i++;
            }
        }
        return ans;
    }
};
